applied = 0
for fn in sorted(glob.glob(os.path.join(HERE, "E1-B*.md"))):
    s = open(fn, encoding="utf-8").read()
    parts = re.split(r"(\n### UNX-F\d{5})", s)
    out = [parts[0]]
    changed = False
    for j in range(1, len(parts), 2):
        head = parts[j]
        fid = "F" + head.strip().split("UNX-F")[1][:5]
        body = parts[j + 1] if j + 1 < len(parts) else ""
        if fid in E and "扩写补笔" not in body:
            body = body.rstrip("\n") + "\n" + E[fid] + "\n"
            applied += 1
            changed = True
        out.append(head)
        out.append(body)
    if changed:
        open(fn, "w", encoding="utf-8").write("".join(out))

print("applied:", applied)
